<?php if($pendientes): ?><section class="admin-panel admin-card"><h2 id="preparaciones-anteriores">Preparaciones anteriores por vincular</h2><p>Relaciona cada preparación existente con su artículo operativo. La asociación es explícita: no se fusionan registros por nombre. Después se editará desde el artículo y sus versiones.</p><form method="POST"><input type="hidden" name="m2_csrf" value="<?= $esc($csrf) ?>"><fieldset class="m2-fieldset" <?= $puedeEditar?'':'disabled' ?>><div class="admin-form-grid"><label class="admin-field">Preparación existente<select name="subreceta_id" required><option value="">Elige la preparación</option><?php foreach($pendientes as $p): ?><option value="<?= (int)$p['id'] ?>"><?= $esc($p['nombre'].' · '.$p['rendimiento'].' '.$p['unidad']) ?></option><?php endforeach; ?></select></label><label class="admin-field">Artículo que representa<select name="articulo_id" required><option value="">Elige el artículo operativo</option><?php foreach($opcionesArticulos as $a): ?><option value="<?= (int)$a['id'] ?>"><?= $esc($a['nombre'].' · '.$a['unidad']) ?></option><?php endforeach; ?></select></label></div><label><input type="checkbox" name="confirmar" value="1" required> Confirmo que la preparación corresponde al artículo elegido y conservaré sus versiones.</label><?php if($puedeEditar): ?><p><button class="admin-btn admin-btn--secondary">Vincular preparación existente</button></p><?php endif; ?></fieldset></form></section><?php endif; ?></section>
